const SETUP_KEYS = ['machineTypes', 'suffixDescriptions', 'customers', 'costCentres', 'defaultWorkingTimes', 'contractInfo', 'workingTimes', 'nonWorking'];

// Filled from GET /api/state by loadState() -- see the boot call at the bottom.
let state = null;
let currentUser = null;
let currentUserId = null;
let editTimesUserId = null; // whose day Edit Times shows: yourself, or anyone for an admin
let adminMode = false; // per-browser safety catch; the server checks the real role
