async function api(method, url, body) { const response = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined }); if (response.status === 401) { window.location.href = '/login.html'; throw new Error('Signed out'); } const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`); return data; }
function isAdmin() { return currentUser?.userType === 'admin'; }
function applyClockState(clock) { state.editSessions = clock.editSessions; state.committedDates = clock.committedDates; state.breakState = clock.breakState; state.contracts.forEach((contract) => { contract.activeSessions = clock.activeSessions[contract.id] || {}; }); }
