function reloadState() { return saveQueue.then(loadState).then(renderAll).catch((error) => showToast(`Could not load the latest data: ${error.message}`)); }
function renderAll() { renderCurrentUser(); $('#nav-configuration').classList.toggle('is-hidden', !isAdmin()); renderContracts(); renderWorkingTimes(); renderEditTimes(); renderContractInfo(); }
function setupSnapshot() { const snapshot = { order: JSON.stringify(state.order), contracts: {}, images: {} }; SETUP_KEYS.forEach((key) => { snapshot[key] = JSON.stringify(state[key]); }); state.contracts.forEach(({ activeSessions, image, ...rest }) => { snapshot.contracts[rest.id] = JSON.stringify(rest); snapshot.images[rest.id] = image || null; }); return snapshot; }
// Sends only what changed since the last save, so one person's edit can't
// overwrite someone else's newer change to a different section. Saves are
// queued so they reach the server in order.
function saveState() { const next = setupSnapshot(); const patch = {}; SETUP_KEYS.forEach((key) => { if (next[key] !== savedSnapshot[key]) patch[key] = state[key]; }); const upsert = state.contracts.filter((contract) => next.contracts[contract.id] !== savedSnapshot.contracts[contract.id] || next.images[contract.id] !== savedSnapshot.images[contract.id]).map(({ activeSessions, image, ...rest }) => (next.images[rest.id] !== savedSnapshot.images[rest.id] ? { ...rest, image: image || null } : rest)); if (upsert.length || next.order !== savedSnapshot.order) patch.contracts = { upsert, order: state.order }; savedSnapshot = next; if (!Object.keys(patch).length) return true; saveQueue = saveQueue.then(() => api('PATCH', '/api/setup', patch)).catch((error) => { showToast(`Could not save: ${error.message}`); setTimeout(reloadState); }); return true; }
function saveSessions(sessions) { renderEditTimes(); api('PATCH', '/api/sessions', { changes: sessions.map(({ id, start, end, unlinked }) => ({ id, start, end, unlinked: Boolean(unlinked) })) }).then((clock) => { applyClockState(clock); renderEditTimes(); renderContracts(); }).catch((error) => { showToast(error.message); reloadState(); }); }
function sessionSecondsFor(contractId, filterFn) { const sessions = state.editSessions[contractId] || []; return sessions.filter(filterFn).reduce((sum, session) => sum + Math.max(0, (timeToMinutes(session.end) - timeToMinutes(session.start)) * 60), 0); }
function todaySessionSecondsForUser(contractId, userId) { return sessionSecondsFor(contractId, (session) => session.date === TODAY && session.userId === userId); }
function lifetimeSessionSeconds(contractId) { return sessionSecondsFor(contractId, () => true); }
function lifetimeSessionSecondsForUser(contractId, userId) { return sessionSecondsFor(contractId, (session) => session.userId === userId); }
function contractSeconds(contract, userId = currentUserId) { const myStart = contract.activeSessions?.[userId]; const live = myStart ? Math.floor((Date.now() - myStart) / 1000) : 0; return lifetimeSessionSecondsForUser(contract.id, userId) + live; }
function isDateCommitted(date, userId = editTimesUserId) { return state.committedDates.some((item) => item.userId === userId && item.date === date); }
function nonWorkingSeconds(entry) { const [startHour, startMinute] = entry.start.split(':').map(Number); const [endHour, endMinute] = entry.end.split(':').map(Number); return Math.max(0, (endHour * 60 + endMinute - startHour * 60 - startMinute) * 60); }
