function updateDragTooltip(handle, target, event) { const tooltip = $('#drag-tooltip'); tooltip.textContent = `${handle.dataset.handle === 'start' ? 'Start' : 'End'}: ${target[handle.dataset.handle]}`; tooltip.style.left = `${event.clientX + 12}px`; tooltip.style.top = `${event.clientY - 38}px`; tooltip.classList.remove('is-hidden'); }
