function enableScheduleHandle(handle) { let resizing = false; let startX; let originalStart; let originalEnd; const entry = state.workingTimes.find((item) => item.id === handle.dataset.entryId); const breakItem = entry?.breaks.find((item) => item.id === handle.dataset.breakId); const target = breakItem || entry; handle.title = `Drag to adjust ${handle.dataset.handle} time`; handle.addEventListener('pointerdown', (event) => { event.preventDefault(); event.stopPropagation(); resizing = true; startX = event.clientX; originalStart = timeToMinutes(target.start); originalEnd = timeToMinutes(target.end); handle.setPointerCapture(event.pointerId); document.body.classList.add('is-resizing'); updateDragTooltip(handle, target, event); }); handle.addEventListener('pointermove', (event) => { if (!resizing) return; const lane = handle.closest('.timeline-lane'); const delta = Math.round((event.clientX - startX) / lane.getBoundingClientRect().width * 1440); if (handle.dataset.handle === 'start') target.start = minutesToTime(Math.min(originalEnd - 1, Math.max(0, originalStart + delta))); else target.end = minutesToTime(Math.max(originalStart + 1, Math.min(1440, originalEnd + delta))); const block = handle.closest(breakItem ? '.break-block' : '.scheduled-block'); const start = timeToMinutes(target.start); const end = timeToMinutes(target.end); block.style.left = `${start / 1440 * 100}%`; block.style.width = `${Math.max(0, end - start) / 1440 * 100}%`; if (!breakItem) { const row = handle.closest('.schedule-row'); row.querySelector(`[data-entry-field="start"]`).value = target.start; row.querySelector(`[data-entry-field="end"]`).value = target.end; } updateDragTooltip(handle, target, event); }); handle.addEventListener('pointerup', (event) => { if (!resizing) return; resizing = false; handle.releasePointerCapture(event.pointerId); document.body.classList.remove('is-resizing'); hideDragTooltip(); saveState(); renderWorkingTimes(); updateMetrics(); }); handle.addEventListener('pointercancel', () => { if (!resizing) return; resizing = false; document.body.classList.remove('is-resizing'); hideDragTooltip(); }); }
function workingTimeRowTemplate(entry) { const user = state.users.find((item) => item.id === entry.userId); const name = user?.name || 'Unknown user'; const start = timeToMinutes(entry.start); const end = timeToMinutes(entry.end); const workWidth = Math.max(0, end - start) / 1440 * 100; return `<div class="schedule-row"><div class="user-cell"><div class="user-name-line"><strong class="working-time-name">${esc(name)}</strong><button class="remove-user" data-entry-id="${esc(entry.id)}" type="button" title="Remove ${esc(name)}" aria-label="Remove ${esc(name)}">&times;</button></div><span><input type="time" data-entry-id="${esc(entry.id)}" data-entry-field="start" value="${esc(entry.start)}"> - <input type="time" data-entry-id="${esc(entry.id)}" data-entry-field="end" value="${esc(entry.end)}"></span><button class="add-break" data-entry-id="${esc(entry.id)}" type="button" title="Manage breaks for ${esc(name)}">+ break</button></div><div class="timeline-lane"><div class="scheduled-block" style="left:${start / 1440 * 100}%;width:${workWidth}%"><button class="schedule-handle start-handle" data-entry-id="${esc(entry.id)}" data-handle="start" type="button" title="Drag to adjust start time" aria-label="Adjust ${esc(name)} start time"></button><button class="schedule-handle end-handle" data-entry-id="${esc(entry.id)}" data-handle="end" type="button" title="Drag to adjust end time" aria-label="Adjust ${esc(name)} end time"></button></div>${entry.breaks.map((breakItem) => `<div class="break-block edit-break" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" style="left:${timeToMinutes(breakItem.start) / 1440 * 100}%;width:${Math.max(1, timeToMinutes(breakItem.end) - timeToMinutes(breakItem.start)) / 1440 * 100}%" title="Edit ${esc(breakItem.type)}: ${esc(breakItem.start)} - ${esc(breakItem.end)}"><button class="schedule-handle start-handle break-handle" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" data-handle="start" type="button" title="Drag to adjust break start time" aria-label="Adjust ${esc(breakItem.type)} start time"></button><button class="schedule-handle end-handle break-handle" data-entry-id="${esc(entry.id)}" data-break-id="${esc(breakItem.id)}" data-handle="end" type="button" title="Drag to adjust break end time" aria-label="Adjust ${esc(breakItem.type)} end time"></button></div>`).join('')}</div></div>`; }
function removeWorkingTimeEntry(entryId) { const entry = state.workingTimes.find((item) => item.id === entryId); if (!entry) return; const name = state.users.find((item) => item.id === entry.userId)?.name || 'this person'; showConfirm(`Clear the working times for ${name}? They will stay in Time Slide.`, 'Clear').then((confirmed) => { if (!confirmed) return; state.workingTimes = state.workingTimes.filter((item) => item.id !== entryId); saveState(); renderWorkingTimes(); updateMetrics(); showToast('Working time entry removed'); }); }
