function openContractModal(contractId = null) { editingContractId = contractId; const contract = contractId ? state.contracts.find((item) => item.id === contractId) : null; $('#contract-modal-title').textContent = contract ? 'Edit tile' : 'Add tile'; $('#contract-submit').innerHTML = contract ? 'Save changes' : '<span>+</span> Add tile'; $('#contract-customer-name').innerHTML = customerOptionsHtml(contract?.customerName || ''); $('#contract-number').innerHTML = contractNumberOptionsHtml(contract?.number || ''); refreshContractSuffixOptions(contract?.suffix || ''); $('#contract-suffix-description').value = contract?.suffixDescription || ''; $('#contract-machine-type').value = contract?.machineType || ''; $('#contract-image').value = ''; $('#contract-image-preview').innerHTML = safeImage(contract?.image) ? `<img src="${esc(contract.image)}" alt="Current image"><span>Current image — choose a file to replace it</span>` : ''; $('#contract-modal').classList.remove('is-hidden'); $('#contract-customer-name').focus(); }
function renderScheduleBreakRows() { const container = $('#schedule-break-rows'); container.innerHTML = scheduleBreaksDraft.map((brk, index) => { const isLast = index === scheduleBreaksDraft.length - 1; return `<div class="form-row break-row"><label>Break starts<input type="time" data-break-index="${index}" data-break-field="start" value="${esc(brk.start)}"></label><label>Break ends<input type="time" data-break-index="${index}" data-break-field="end" value="${esc(brk.end)}"></label><button class="break-row-action ${isLast ? 'add-break-row' : 'remove-break-row'}" data-break-index="${index}" type="button" title="${isLast ? 'Add another break' : 'Remove this break'}" aria-label="${isLast ? 'Add another break' : 'Remove this break'}">${isLast ? '&#43;' : '&times;'}</button></div>`; }).join(''); container.querySelectorAll('[data-break-field]').forEach((input) => input.addEventListener('change', () => { scheduleBreaksDraft[Number(input.dataset.breakIndex)][input.dataset.breakField] = input.value; })); container.querySelectorAll('.add-break-row').forEach((button) => button.addEventListener('click', () => { scheduleBreaksDraft.push({ start: '12:30', end: '13:05' }); renderScheduleBreakRows(); })); container.querySelectorAll('.remove-break-row').forEach((button) => button.addEventListener('click', () => { scheduleBreaksDraft.splice(Number(button.dataset.breakIndex), 1); renderScheduleBreakRows(); })); }
function openScheduleModal(entryId = null) { editingScheduleEntryId = entryId; const entry = state.workingTimes.find((item) => item.id === entryId); const user = entry ? state.users.find((item) => item.id === entry.userId) : null; $('#schedule-modal-title').textContent = user ? `Edit ${user.name}` : 'Add user'; const select = $('#schedule-user-name'); const assignedIds = new Set(state.workingTimes.map((item) => item.userId)); const availableUsers = state.users.filter((item) => item.id === entry?.userId || !assignedIds.has(item.id)); select.innerHTML = '<option value="">Select user</option>' + availableUsers.map((item) => `<option value="${esc(item.id)}" ${entry && item.id === entry.userId ? 'selected' : ''}>${esc(item.name)}</option>`).join(''); select.disabled = Boolean(entry); $('#schedule-start').value = entry?.start || '06:00'; $('#schedule-end').value = entry?.end || '15:00'; scheduleBreaksDraft = entry && entry.breaks.length ? entry.breaks.map((brk) => ({ id: brk.id, start: brk.start, end: brk.end })) : [{ start: '12:30', end: '13:05' }]; renderScheduleBreakRows(); $('#schedule-modal').classList.remove('is-hidden'); $('#schedule-user-name').focus(); }
function closeScheduleModal() { $('#schedule-modal').classList.add('is-hidden'); $('#schedule-form').reset(); $('#schedule-user-name').disabled = false; editingScheduleEntryId = null; scheduleBreaksDraft = []; }
function saveSchedule(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const existingEntry = editingScheduleEntryId ? state.workingTimes.find((item) => item.id === editingScheduleEntryId) : null; const targetUserId = existingEntry ? existingEntry.userId : formData.get('userId'); const start = formData.get('start'); const end = formData.get('end'); if (!targetUserId) { showToast('Select a user'); return; } if (timeToMinutes(end) <= timeToMinutes(start)) { showToast('End time must be after start time'); return; } for (const brk of scheduleBreaksDraft) { if (timeToMinutes(brk.end) <= timeToMinutes(brk.start)) { showToast('Break end times must be after start times'); return; } } const breaks = scheduleBreaksDraft.map((brk, index) => ({ id: brk.id || `break-${Date.now()}-${index}`, type: 'Break', start: brk.start, end: brk.end })); if (existingEntry) { existingEntry.start = start; existingEntry.end = end; existingEntry.breaks = breaks; } else { state.workingTimes.push({ id: `wt-${Date.now()}`, userId: targetUserId, start, end, breaks }); } saveState(); renderWorkingTimes(); updateMetrics(); closeScheduleModal(); showToast(existingEntry ? 'Working times updated' : 'Working times added'); }
function closeContractModal() { $('#contract-modal').classList.add('is-hidden'); $('#contract-form').reset(); $('#contract-image-preview').innerHTML = ''; editingContractId = null; }
function saveContract(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const customerName = formData.get('customerName').trim(); const number = formData.get('number').trim(); const suffix = formData.get('suffix').trim(); const suffixDescription = formData.get('suffixDescription').trim(); const machineType = formData.get('machineType'); const imageFile = formData.get('image'); const contractId = editingContractId; const finishSaveContract = (image) => { if (contractId) { const contract = state.contracts.find((item) => item.id === contractId); contract.customerName = customerName; contract.number = number; contract.suffix = suffix; contract.suffixDescription = suffixDescription; contract.machineType = machineType; if (image) contract.image = image; } else { const id = `contract-${Date.now()}`; state.contracts.push({ id, customerName, number, suffix, suffixDescription, machineType, image, activeSessions: {}, pinned: false, hidden: false }); state.order.push(id); } saveState(); renderContracts(); renderEditTimes(); closeContractModal(); showToast(contractId ? 'Tile updated' : 'Tile added to dashboard'); }; const proceedWithSave = () => { if (imageFile && imageFile.size) { const reader = new FileReader(); reader.onload = () => finishSaveContract(reader.result); reader.readAsDataURL(imageFile); } else { finishSaveContract(null); } }; const isDuplicate = !contractId && state.contracts.some((item) => item.customerName === customerName && item.number === number && item.suffix === suffix); if (isDuplicate) { showConfirm('A tile for this customer, contract number and suffix already exists. Add it anyway?').then((confirmed) => { if (confirmed) proceedWithSave(); }); } else { proceedWithSave(); } }
