function levenshteinDistance(a, b) { const rows = a.length + 1; const cols = b.length + 1; const dp = Array.from({ length: rows }, () => new Array(cols).fill(0)); for (let i = 0; i < rows; i += 1) dp[i][0] = i; for (let j = 0; j < cols; j += 1) dp[0][j] = j; for (let i = 1; i < rows; i += 1) { for (let j = 1; j < cols; j += 1) { dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]); } } return dp[rows - 1][cols - 1]; }
function textSimilarity(a, b) { const distance = levenshteinDistance(a.toLowerCase(), b.toLowerCase()); const maxLength = Math.max(a.length, b.length) || 1; return 1 - distance / maxLength; }
function findSimilarEntry(value, list, threshold = 0.75) { let best = null; let bestScore = 0; list.forEach((item) => { const score = textSimilarity(value, item); if (score > bestScore) { bestScore = score; best = item; } }); return bestScore >= threshold ? best : null; }
function renderSuffixDescriptionList() { const list = $('#suffix-description-list'); list.innerHTML = state.suffixDescriptions.length ? state.suffixDescriptions.map((desc) => `<li>${esc(desc)}<button class="remove-list-item" data-suffix-desc="${esc(desc)}" type="button" aria-label="Remove ${esc(desc)}">&times;</button></li>`).join('') : '<li class="list-empty">No suffix descriptions yet.</li>'; list.querySelectorAll('.remove-list-item').forEach((button) => button.addEventListener('click', () => removeSuffixDescription(button.dataset.suffixDesc))); }
function addSuffixDescription(event) { event.preventDefault(); const input = $('#suffix-description-input'); const value = input.value.trim(); if (!value) return; const exactMatch = state.suffixDescriptions.find((item) => item.toLowerCase() === value.toLowerCase()); if (exactMatch) { showToast('That suffix description already exists'); input.value = ''; return; } const commit = () => { state.suffixDescriptions.push(value); input.value = ''; saveState(); renderSuffixDescriptionList(); }; const similar = findSimilarEntry(value, state.suffixDescriptions); if (similar) { showConfirm(`This looks similar to "${similar}". Add it anyway?`).then((confirmed) => { if (confirmed) commit(); }); } else { commit(); } }
