async function testSysproEnet() { const button = $('#config-test-enet'); const result = $('#config-test-result'); if (configDirty && !(await saveSysproConfig())) return; button.disabled = true; button.textContent = 'Testing…'; result.className = 'config-test-result'; result.textContent = 'Contacting Syspro…'; try { const outcome = await api('POST', '/api/config/syspro/test-enet'); result.classList.add(outcome.ok ? 'is-ok' : 'is-error'); result.textContent = outcome.message; } catch (error) { result.classList.add('is-error'); result.textContent = error.message; } finally { button.disabled = false; button.textContent = 'Test connection'; } }
function timeOfDayGreeting() { const hour = new Date().getHours(); if (hour < 12) return 'Good morning'; if (hour < 18) return 'Good afternoon'; return 'Good evening'; }
