function renderDefaultWorkingTimes() { $('#default-wt-start').value = state.defaultWorkingTimes.start; $('#default-wt-end').value = state.defaultWorkingTimes.end; $('#default-wt-break1-start').value = state.defaultWorkingTimes.breaks[0].start; $('#default-wt-break1-end').value = state.defaultWorkingTimes.breaks[0].end; $('#default-wt-break2-start').value = state.defaultWorkingTimes.breaks[1].start; $('#default-wt-break2-end').value = state.defaultWorkingTimes.breaks[1].end; }
