// Pauses the running clock when the signed-in user's scheduled break starts and
// resumes it afterwards. The server does the actual stop/start; this only
// notices the time. On failure it waits 30s rather than retrying every tick.
let breakRequestPending = false;
let breakRetryAt = 0;
function handleBreakState() { if (breakRequestPending || Date.now() < breakRetryAt) return; const breakItem = currentBreak(currentUserId); const running = state.contracts.find((contract) => contract.activeSessions?.[currentUserId]); let action = null; if (breakItem && !state.breakState && running) action = 'pause'; else if (!breakItem && state.breakState) action = 'resume'; if (!action) return; const contract = action === 'pause' ? running : state.contracts.find((item) => item.id === state.breakState.contractId); breakRequestPending = true; api('POST', `/api/clock/break/${action}`).then((clock) => { applyClockState(clock); renderContracts(); renderEditTimes(); if (action === 'pause') showToast(`${contract.customerName} paused for break`); else if (contract && clock.activeSessions[contract.id]?.[currentUserId]) showToast(`${contract.customerName} resumed after break`); }).catch((error) => { breakRetryAt = Date.now() + 30000; showToast(error.message); }).finally(() => { breakRequestPending = false; }); }
function tick() { handleBreakState(); updateGreeting(); state.contracts.forEach((contract) => { const myStart = contract.activeSessions?.[currentUserId]; if (!myStart) return; const live = document.querySelector(`[data-live-id="${contract.id}"]`); if (live) live.textContent = formatTime(Math.floor((Date.now() - myStart) / 1000)); const accum = document.querySelector(`[data-accum-id="${contract.id}"]`); if (accum) accum.textContent = formatTime(contractSeconds(contract)); }); updateMetrics(); }
